import "server-only";
import { Prisma } from "@prisma/client";
import { z } from "zod";
import db from "@/lib/prisma";
import { requireAlphaSeoProjectAccess } from "@/lib/alpha-seo/project-access";
import { createCsv } from "./csv";
import { createGoogleSheetsClipboard, GOOGLE_SHEETS_NEW_URL } from "./google-sheets";

const inputSchema = z.object({ projectId: z.string().min(1), kind: z.enum(["KEYWORD_RESEARCH", "SAVED_KEYWORDS", "BACKLINKS", "DOMAIN_KEYWORDS", "DOMAIN_PAGES", "AUDIT_ISSUES", "AUDIT_PAGES", "AUDIT_LIGHTHOUSE", "SEARCH_PERFORMANCE", "BRAND_LOOKUP", "PROMPT_EXPLORER"]), rows: z.array(z.record(z.string(), z.unknown())).max(10_000), columns: z.array(z.object({ key: z.string().min(1).max(100), label: z.string().min(1).max(100) })).min(1).max(100), title: z.string().trim().min(1).max(120).default("Alpha SEO Export") });
function scalar(value: unknown): string | number | boolean | null { return typeof value === "string" || typeof value === "number" || typeof value === "boolean" ? value : value == null ? null : JSON.stringify(value); }
export async function exportAlphaSeoCsv(input: unknown) { const parsed = inputSchema.parse(input); const access = await requireAlphaSeoProjectAccess({ projectId: parsed.projectId, action: "seo:export" }); const exportRow = await db.alphaSeoExport.create({ data: { projectId: parsed.projectId, createdById: access.userId, kind: parsed.kind, format: "CSV", filters: {}, columns: parsed.columns as Prisma.InputJsonValue, status: "RUNNING" }, select: { id: true } }); try { const csv = createCsv(parsed.columns.map((column) => column.label), parsed.rows.map((row) => parsed.columns.map((column) => scalar(row[column.key])))); await db.alphaSeoExport.update({ where: { id: exportRow.id }, data: { status: "COMPLETED", completedAt: new Date(), storageRef: `inline:${Buffer.byteLength(csv, "utf8")}` } }); return { exportId: exportRow.id, filename: `${parsed.kind.toLowerCase()}-${new Date().toISOString().slice(0, 10)}.csv`, mimeType: "text/csv;charset=utf-8", content: csv }; } catch (error) { await db.alphaSeoExport.update({ where: { id: exportRow.id }, data: { status: "FAILED", errorCode: error instanceof Error ? error.name : "EXPORT_ERROR" } }); throw error; } }
export async function exportAlphaSeoGoogleSheets(input: unknown) { const parsed = inputSchema.parse(input); const access = await requireAlphaSeoProjectAccess({ projectId: parsed.projectId, action: "seo:export" }); const exportRow = await db.alphaSeoExport.create({ data: { projectId: parsed.projectId, createdById: access.userId, kind: parsed.kind, format: "GOOGLE_SHEETS", filters: {}, columns: parsed.columns as Prisma.InputJsonValue, status: "RUNNING" }, select: { id: true } }); try { const clipboardText = createGoogleSheetsClipboard(parsed.columns.map((column) => column.label), parsed.rows.map((row) => parsed.columns.map((column) => scalar(row[column.key])))); await db.alphaSeoExport.update({ where: { id: exportRow.id }, data: { status: "COMPLETED", completedAt: new Date(), storageRef: `clipboard:${Buffer.byteLength(clipboardText, "utf8")}` } }); return { exportId: exportRow.id, title: parsed.title, clipboardText, spreadsheetUrl: GOOGLE_SHEETS_NEW_URL, rowCount: parsed.rows.length }; } catch (error) { await db.alphaSeoExport.update({ where: { id: exportRow.id }, data: { status: "FAILED", errorCode: error instanceof Error ? error.name : "EXPORT_ERROR" } }); throw error; } }
